void Solver::bump_var(int var, double coeff) {
    // ignore zero coefficient bumps
    if (coeff == 0.0) return;

    // compute increment once
    double inc = var_inc * coeff;
    activity[var] += inc;

    // Lazy rescaling to avoid overflow without scanning all variables each time
    if (activity[var] > 1e100) {
        const double scale = 1e-100;
        for (int i = 1; i <= vars; ++i) activity[i] *= scale;
        var_inc *= scale;
    }

    // Ensure the variable is present in the VSIDS heap and update its priority
    if (vsids.inHeap(var)) {
        vsids.update(var);
    } else {
        vsids.insert(var);
    }
}
